from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-intermediate-19","course_id":"html-intermediate","title":"figure و figcaption","slug":"html-intermediate-19","summary":"figure و figcaption: گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;figure&gt;&lt;img src=\"tree.png\" alt=\"درخت عناصر HTML\"&gt;&lt;figcaption&gt;شکل ۱: ساختار سند&lt;/figcaption&gt;&lt;/figure&gt;</code></pre><h3>تمرین</h3><p>برای نمودار آموزشی شرح دقیق بنویس.</p><h3>نکته فنی</h3><p>figure محتوای مستقل مانند تصویر یا نمودار را گروه‌بندی می‌کند و figcaption شرح آن است.</p><h3>معیار موفقیت</h3><p>تصویر و شرح آن در یک figure قرار گیرند و figcaption رابطه روشن داشته باشد.</p>","starter_code":"<figure><img src=\"tree.png\" alt=\"درخت عناصر HTML\"><figcaption>شکل ۱: ساختار سند</figcaption></figure>","exercise":"برای نمودار آموزشی شرح دقیق بنویس.","status":"published","sort_order":19,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-20","course_id":"html-intermediate","title":"SVG دسترس‌پذیر","slug":"html-intermediate-20","summary":"SVG دسترس‌پذیر: گرافیک برداری درون‌خطی با عنوان قابل شناسایی.","content_html":"<h3>هدف درس</h3><p>گرافیک برداری درون‌خطی با عنوان قابل شناسایی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"&gt;&lt;title id=\"t\"&gt;دو ستون&lt;/title&gt;&lt;rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/&gt;&lt;rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/&gt;&lt;/svg&gt;</code></pre><h3>تمرین</h3><p>SVG با دو شکل و عنوان توصیفی بساز.</p><h3>نکته فنی</h3><p>برای SVG اطلاعاتی title یا نام دسترس‌پذیر فراهم کن؛ SVG تزئینی را از درخت دسترس‌پذیری پنهان کن.</p><h3>معیار موفقیت</h3><p>SVG اطلاعاتی نام دسترس‌پذیر داشته باشد و محتوای بصری آن برای کاربر قابل فهم باشد.</p>","starter_code":"<svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"><title id=\"t\">دو ستون</title><rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/><rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/></svg>","exercise":"SVG با دو شکل و عنوان توصیفی بساز.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-21","course_id":"html-intermediate","title":"noscript","slug":"html-intermediate-21","summary":"noscript: نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.","content_html":"<h3>هدف درس</h3><p>نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;noscript&gt;&lt;p&gt;برای این قابلیت JavaScript را فعال کن.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.</p><h3>نکته فنی</h3><p>noscript فقط وقتی JavaScript غیرفعال یا پشتیبانی‌نشده باشد نمایش داده می‌شود؛ محتوای اصلی را بی‌جهت به آن وابسته نکن.</p><h3>معیار موفقیت</h3><p>پیام جایگزین فقط در حالت بدون JavaScript دیده شود و محتوای اصلی همچنان قابل دسترس بماند.</p>","starter_code":"<noscript><p>برای این قابلیت JavaScript را فعال کن.</p></noscript>","exercise":"پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-22","course_id":"html-intermediate","title":"loading lazy","slug":"html-intermediate-22","summary":"loading lazy: به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.","content_html":"<h3>هدف درس</h3><p>به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\"&gt;</code></pre><h3>تمرین</h3><p>برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.</p><h3>نکته فنی</h3><p>loading=lazy را برای رسانه‌های خارج از viewport به کار ببر، نه تصویر اصلی بالای صفحه.</p><h3>معیار موفقیت</h3><p>تصویر پایین صفحه تنبل بارگذاری شود و تصویر اصلی بالای صفحه بی‌دلیل تأخیر نداشته باشد.</p>","starter_code":"<img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\">","exercise":"برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.","status":"published","sort_order":22,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-23","course_id":"html-intermediate","title":"fetchpriority","slug":"html-intermediate-23","summary":"fetchpriority: پیشنهاد اولویت دریافت منبع مهم برای مرورگر.","content_html":"<h3>هدف درس</h3><p>پیشنهاد اولویت دریافت منبع مهم برای مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\"&gt;</code></pre><h3>تمرین</h3><p>برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.</p><h3>نکته فنی</h3><p>fetchpriority یک hint اولویت است و نباید برای تعداد زیادی منبع high تعیین شود.</p><h3>معیار موفقیت</h3><p>اولویت بالا فقط به منبع واقعاً حیاتی داده شود و منابع دیگر اولویت عادی داشته باشند.</p>","starter_code":"<img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\">","exercise":"برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.","status":"published","sort_order":23,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-24","course_id":"html-intermediate","title":"iframe sandbox","slug":"html-intermediate-24","summary":"iframe sandbox: محدودکردن قابلیت‌های محتوای جاسازی‌شده.","content_html":"<h3>هدف درس</h3><p>محدودکردن قابلیت‌های محتوای جاسازی‌شده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"&gt;&lt;/iframe&gt;</code></pre><h3>تمرین</h3><p>رفتار iframe محدود را بررسی کن.</p><h3>نکته فنی</h3><p>sandbox قابلیت‌های iframe را محدود می‌کند؛ فقط tokenهای واقعاً لازم را اضافه کن.</p><h3>معیار موفقیت</h3><p>iframe فقط قابلیت‌های ضروری را دریافت کند و محتوای تعبیه‌شده در محدوده sandbox بماند.</p>","starter_code":"<iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"></iframe>","exercise":"رفتار iframe محدود را بررسی کن.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-25","course_id":"html-intermediate","title":"defer و async","slug":"html-intermediate-25","summary":"defer و async: تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.","content_html":"<h3>هدف درس</h3><p>تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script src=\"app.js\" defer&gt;&lt;/script&gt;&lt;script src=\"metrics.js\" async&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.</p><h3>نکته فنی</h3><p>defer ترتیب اجرای اسکریپت‌های deferred را حفظ می‌کند؛ async ترتیب اجرا را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>اسکریپت‌های defer به ترتیب سند اجرا شوند و async مستقل از ترتیب بارگذاری عمل کند.</p>","starter_code":"<script src=\"app.js\" defer></script><script src=\"metrics.js\" async></script>","exercise":"برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-26","course_id":"html-intermediate","title":"JavaScript module","slug":"html-intermediate-26","summary":"JavaScript module: بارگذاری فایل به‌عنوان ماژول با scope مستقل.","content_html":"<h3>هدف درس</h3><p>بارگذاری فایل به‌عنوان ماژول با scope مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script type=\"module\" src=\"main.js\"&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>فایل اصلی را به ماژول app.js متصل کن.</p><h3>نکته فنی</h3><p>script type=module به‌طور پیش‌فرض deferred است و از scope ماژولی استفاده می‌کند.</p><h3>معیار موفقیت</h3><p>ماژول بدون خطای type=module بارگذاری شود و import/export در فایل ماژول معتبر باشد.</p>","starter_code":"<script type=\"module\" src=\"main.js\"></script>","exercise":"فایل اصلی را به ماژول app.js متصل کن.","status":"published","sort_order":26,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-27","course_id":"html-intermediate","title":"preconnect","slug":"html-intermediate-27","summary":"preconnect: شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.","content_html":"<h3>هدف درس</h3><p>شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>برای منبع خارجی واقعی preconnect تعریف کن.</p><h3>نکته فنی</h3><p>preconnect برای originهایی مفید است که احتمالاً به‌زودی به آن‌ها اتصال برقرار می‌شود؛ از اتصال‌های اضافی بپرهیز.</p><h3>معیار موفقیت</h3><p>اتصال اولیه فقط برای origin لازم انجام شود و منبع خارجی غیرضروری اضافه نشود.</p>","starter_code":"<link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin>","exercise":"برای منبع خارجی واقعی preconnect تعریف کن.","status":"published","sort_order":27,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-28","course_id":"html-intermediate","title":"preload","slug":"html-intermediate-28","summary":"preload: دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.","content_html":"<h3>هدف درس</h3><p>دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>فونت پروژه را با as و type درست preload کن.</p><h3>نکته فنی</h3><p>preload برای منبع ضروری همین صفحه است؛ نوع و crossorigin باید با درخواست واقعی هماهنگ باشد.</p><h3>معیار موفقیت</h3><p>منبع preload واقعاً در همان صفحه مصرف شود و نوع و crossorigin با فایل هماهنگ باشد.</p>","starter_code":"<link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>","exercise":"فونت پروژه را با as و type درست preload کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-29","course_id":"html-intermediate","title":"skip link","slug":"html-intermediate-29","summary":"skip link: پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.","content_html":"<h3>هدف درس</h3><p>پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;nav&gt;...&lt;/nav&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;...&lt;/main&gt;</code></pre><h3>تمرین</h3><p>لینک پرش بساز و فوکوس مقصد را بررسی کن.</p><h3>نکته فنی</h3><p>skip link باید به مقصدی با id معتبر برسد و هنگام فعال‌سازی با صفحه‌کلید قابل استفاده باشد.</p><h3>معیار موفقیت</h3><p>پیوند پرش به محتوا با صفحه‌کلید کار کند و مقصد main قابل تمرکز باشد.</p>","starter_code":"<a href=\"#main\">رفتن به محتوا</a><nav>...</nav><main id=\"main\" tabindex=\"-1\">...</main>","exercise":"لینک پرش بساز و فوکوس مقصد را بررسی کن.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-30","course_id":"html-intermediate","title":"tabindex","slug":"html-intermediate-30","summary":"tabindex: کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.","content_html":"<h3>هدف درس</h3><p>کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;h2 id=\"result\" tabindex=\"-1\"&gt;نتیجه&lt;/h2&gt;&lt;button&gt;ادامه&lt;/button&gt;</code></pre><h3>تمرین</h3><p>برای مقصد لینک پرش tabindex منفی یک بگذار.</p><h3>نکته فنی</h3><p>tabindex مثبت ترتیب طبیعی فوکوس را مختل می‌کند؛ برای ترتیب عادی از صفر یا بدون tabindex استفاده کن.</p><h3>معیار موفقیت</h3><p>ترتیب Tab طبیعی و قابل پیش‌بینی باشد و tabindex مثبت غیرضروری وجود نداشته باشد.</p>","starter_code":"<h2 id=\"result\" tabindex=\"-1\">نتیجه</h2><button>ادامه</button>","exercise":"برای مقصد لینک پرش tabindex منفی یک بگذار.","status":"published","sort_order":30,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-31","course_id":"html-intermediate","title":"inert و hidden","slug":"html-intermediate-31","summary":"inert و hidden: inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.","content_html":"<h3>هدف درس</h3><p>inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;section hidden&gt;پنل مخفی&lt;/section&gt;&lt;div inert&gt;&lt;button&gt;غیرفعال&lt;/button&gt;&lt;/div&gt;</code></pre><h3>تمرین</h3><p>تفاوت نمایش و تعامل را آزمایش کن.</p><h3>نکته فنی</h3><p>inert تعامل و فوکوس زیرشاخه را غیرفعال می‌کند؛ hidden عنصر را از نمایش عادی حذف می‌کند.</p><h3>معیار موفقیت</h3><p>بخش inert قابل تعامل نباشد و بخش hidden در صفحه نمایش داده نشود.</p>","starter_code":"<section hidden>پنل مخفی</section><div inert><button>غیرفعال</button></div>","exercise":"تفاوت نمایش و تعامل را آزمایش کن.","status":"published","sort_order":31,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-32","course_id":"html-intermediate","title":"aria-live","slug":"html-intermediate-32","summary":"aria-live: اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.","content_html":"<h3>هدف درس</h3><p>اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\"&gt;آماده&lt;/p&gt;&lt;button onclick=\"status.textContent='ذخیره شد'\"&gt;ذخیره&lt;/button&gt;</code></pre><h3>تمرین</h3><p>ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.</p><h3>نکته فنی</h3><p>aria-live را فقط برای پیام‌های واقعاً پویا به کار ببر تا صفحه‌خوان با اعلان‌های پی‌درپی آزار نبیند.</p><h3>معیار موفقیت</h3><p>پیام پویا یک بار و با متن مناسب به صفحه‌خوان اعلام شود.</p>","starter_code":"<p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\">آماده</p><button onclick=\"status.textContent='ذخیره شد'\">ذخیره</button>","exercise":"ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-33","course_id":"html-intermediate","title":"rowspan و colspan","slug":"html-intermediate-33","summary":"rowspan و colspan: گسترش سلول جدول در چند ردیف یا ستون.","content_html":"<h3>هدف درس</h3><p>گسترش سلول جدول در چند ردیف یا ستون.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th rowspan=\"2\"&gt;نام&lt;/th&gt;&lt;th colspan=\"2\"&gt;نمره&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th&gt;HTML&lt;/th&gt;&lt;th&gt;CSS&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;سارا&lt;/td&gt;&lt;td&gt;90&lt;/td&gt;&lt;td&gt;85&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول چندسطحی بساز و سلول‌های منطقی را بشمار.</p><h3>نکته فنی</h3><p>rowspan و colspan ساختار جدول را پیچیده می‌کنند؛ برای جدول‌های پیچیده ارتباط سرستون‌ها را صریح کن.</p><h3>معیار موفقیت</h3><p>سلول‌های ادغام‌شده در جدول درست نمایش داده شوند و رابطه سرستون‌ها قابل تشخیص باشد.</p>","starter_code":"<table><tr><th rowspan=\"2\">نام</th><th colspan=\"2\">نمره</th></tr><tr><th>HTML</th><th>CSS</th></tr><tr><td>سارا</td><td>90</td><td>85</td></tr></table>","exercise":"جدول چندسطحی بساز و سلول‌های منطقی را بشمار.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-34","course_id":"html-intermediate","title":"headers در جدول","slug":"html-intermediate-34","summary":"headers در جدول: ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.","content_html":"<h3>هدف درس</h3><p>ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th id=\"student\"&gt;دانش‌آموز&lt;/th&gt;&lt;th id=\"html\"&gt;HTML&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td headers=\"student\"&gt;علی&lt;/td&gt;&lt;td headers=\"html\"&gt;88&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول نمره با id و headers بساز.</p><h3>نکته فنی</h3><p>headers باید به id سرستون‌های مرتبط اشاره کند؛ مقدارها با فاصله از هم جدا می‌شوند.</p><h3>معیار موفقیت</h3><p>هر سلول داده در جدول پیچیده به سرستون‌های مربوط با headers وصل شود.</p>","starter_code":"<table><tr><th id=\"student\">دانش‌آموز</th><th id=\"html\">HTML</th></tr><tr><td headers=\"student\">علی</td><td headers=\"html\">88</td></tr></table>","exercise":"جدول نمره با id و headers بساز.","status":"published","sort_order":34,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-35","course_id":"html-intermediate","title":"time و datetime","slug":"html-intermediate-35","summary":"time و datetime: ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.","content_html":"<h3>هدف درس</h3><p>ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;time datetime=\"2026-11-07\"&gt;۷ نوامبر ۲۰۲۶&lt;/time&gt;</code></pre><h3>تمرین</h3><p>تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.</p><h3>نکته فنی</h3><p>time باید datetime ماشین‌خوان معتبر داشته باشد و متن داخل عنصر می‌تواند قالب محلی داشته باشد.</p><h3>معیار موفقیت</h3><p>تاریخ برای ماشین با datetime قابل خواندن و برای انسان با متن محلی نمایش داده شود.</p>","starter_code":"<time datetime=\"2026-11-07\">۷ نوامبر ۲۰۲۶</time>","exercise":"تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.","status":"published","sort_order":35,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-36","course_id":"html-intermediate","title":"پروژه پایانی داشبورد آموزشی","slug":"html-intermediate-36","summary":"پروژه پایانی داشبورد آموزشی: ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.","content_html":"<h3>هدف درس</h3><p>ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;!doctype html&gt;&lt;html lang=\"fa\" dir=\"rtl\"&gt;&lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"&gt;&lt;title&gt;داشبورد دوره&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;header&gt;&lt;h1&gt;داشبورد دوره&lt;/h1&gt;&lt;/header&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;&lt;section&gt;&lt;h2&gt;پیشرفت&lt;/h2&gt;&lt;progress value=\"6\" max=\"10\"&gt;60%&lt;/progress&gt;&lt;/section&gt;&lt;form&gt;&lt;fieldset&gt;&lt;legend&gt;مسیر آموزشی&lt;/legend&gt;&lt;select&gt;&lt;optgroup label=\"وب\"&gt;&lt;option&gt;HTML&lt;/option&gt;&lt;option&gt;CSS&lt;/option&gt;&lt;/optgroup&gt;&lt;/select&gt;&lt;/fieldset&gt;&lt;button&gt;ثبت آزمایشی&lt;/button&gt;&lt;/form&gt;&lt;details&gt;&lt;summary&gt;راهنما&lt;/summary&gt;&lt;p&gt;درس بعدی را باز کن.&lt;/p&gt;&lt;/details&gt;&lt;p aria-live=\"polite\"&gt;آماده&lt;/p&gt;&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;</code></pre><h3>تمرین</h3><p>داشبوردی با skip link، progress، fieldset، optgroup، details، picture، جدول چندسطحی و aria-live بساز و با صفحه‌کلید و اعتبارسنج HTML بررسی کن.</p><h3>نکته فنی</h3><p>داشبورد نمونه فقط ساختار HTML را نشان می‌دهد؛ داده پویا، احراز هویت و ذخیره‌سازی به لایه‌های دیگر نیاز دارند.</p><h3>معیار موفقیت</h3><p>داشبورد ساختار معنایی، جدول و فرم درست داشته باشد و محدودیت نبود backend مشخص باشد.</p>","starter_code":"<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>داشبورد دوره</title></head><body><a href=\"#main\">رفتن به محتوا</a><header><h1>داشبورد دوره</h1></header><main id=\"main\" tabindex=\"-1\"><section><h2>پیشرفت</h2><progress value=\"6\" max=\"10\">60%</progress></section><form><fieldset><legend>مسیر آموزشی</legend><select><optgroup label=\"وب\"><option>HTML</option><option>CSS</option></optgroup></select></fieldset><button>ثبت آزمایشی</button></form><details><summary>راهنما</summary><p>درس بعدی را باز کن.</p></details><p aria-live=\"polite\">آماده</p></main></body></html>","exercise":"داشبوردی با skip link، progress، fieldset، optgroup، details، picture، جدول چندسطحی و aria-live بساز و با صفحه‌کلید و اعتبارسنج HTML بررسی کن.","status":"published","sort_order":36,"estimated_minutes":75}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();

